 const filterButtons = document.querySelectorAll(".filter-chip");
 const productCards = document.querySelectorAll(".product-card");
 const addButtons = document.querySelectorAll("[data-product]");
 const cartCount = document.getElementById("cart-count");
 const cartStatus = document.getElementById("cart-status");
 const countdown = document.getElementById("countdown");
 const editorialTabs = document.querySelectorAll(".editorial-tab");
 const newsletterForm = document.getElementById("newsletter-form");
 const newsletterInput = document.getElementById("email-input");
 const newsletterStatus = document.getElementById("newsletter-status");

 const stories = [
   {
     kicker: "Journal spotlight",
     title: "How to build a calmer start to the day",
     summary:
       "A soft guide to routines, materials, and lighting choices that create a more grounded morning.",
   },
   {
     kicker: "Packing notes",
     title: "What frequent flyers actually keep within reach",
     summary:
       "A practical edit of pouches, layers, and modular pieces that reduce friction between check-in and arrival.",
   },
   {
     kicker: "Hosting guide",
     title: "Set the table with less, and make it feel warmer",
     summary:
       "Simple serving choices and tonal materials that make casual gatherings look intentional without feeling formal.",
   },
 ];

 let cartItems = 0;
 const dealEndsAt = Date.now() + 3 * 24 * 60 * 60 * 1000 + 4 * 60 * 60 * 1000;

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const filter = button.dataset.filter;

     filterButtons.forEach((chip) => {
       const isActive = chip === button;
       chip.classList.toggle("is-active", isActive);
       chip.setAttribute("aria-pressed", String(isActive));
     });

     productCards.forEach((card) => {
       const matches = filter === "all" || card.dataset.category === filter;
       card.classList.toggle("is-hidden", !matches);
     });
   });
 });

 addButtons.forEach((button) => {
   button.addEventListener("click", () => {
     cartItems += 1;
     cartCount.textContent = String(cartItems);
     cartStatus.textContent = `${button.dataset.product} added to cart. Cart now has ${cartItems} item${cartItems === 1 ? "" : "s"}.`;
   });
 });

 function updateCountdown() {
   const remaining = Math.max(0, dealEndsAt - Date.now());
   const days = Math.floor(remaining / (1000 * 60 * 60 * 24));
   const hours = Math.floor((remaining / (1000 * 60 * 60)) % 24);
   const minutes = Math.floor((remaining / (1000 * 60)) % 60);
   const seconds = Math.floor((remaining / 1000) % 60);

   countdown.textContent = `${String(days).padStart(2, "0")} : ${String(hours).padStart(2, "0")} : ${String(minutes).padStart(2, "0")} : ${String(seconds).padStart(2, "0")}`;
 }

 updateCountdown();
 window.setInterval(updateCountdown, 1000);

 editorialTabs.forEach((tab) => {
   tab.addEventListener("click", () => {
     const story = stories[Number(tab.dataset.story)];
     const title = document.getElementById("story-title");
     const summary = document.getElementById("story-summary");
     const kicker = document.getElementById("story-kicker");

     editorialTabs.forEach((button) => {
       const isActive = button === tab;
       button.classList.toggle("is-active", isActive);
       button.setAttribute("aria-selected", String(isActive));
     });

     kicker.textContent = story.kicker;
     title.textContent = story.title;
     summary.textContent = story.summary;
   });
 });

 newsletterForm.addEventListener("submit", (event) => {
   event.preventDefault();
   newsletterStatus.textContent = `Thanks for joining, ${newsletterInput.value}. You are subscribed for product updates.`;
   newsletterForm.reset();
 });

